package dev.discmount.app

import android.content.Context
import dev.discmount.core.bd.AacsResult
import dev.discmount.core.scsi.DiscKind
import dev.discmount.core.scsi.DiscProfile

/** Idiomas de la interfaz, en este orden (el inglés es el predeterminado). */
enum class Lang(val code: String, val native: String) {
    EN("en", "English"), FR("fr", "Français"), DE("de", "Deutsch"), JA("ja", "日本語"), ES("es", "Español"),
    IT("it", "Italiano"), NL("nl", "Nederlands"), PT("pt", "Português"), KO("ko", "한국어"), RU("ru", "Русский"), CA("ca", "Català");
}

object I18n {
    @Volatile var lang: Lang = Lang.EN; private set
    private const val PREFS = "discmount"

    /** Carga el idioma guardado (inglés si no hay ninguno). */
    fun load(ctx: Context) {
        val c = try { ctx.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString("lang", "en") } catch (e: Exception) { "en" }
        lang = Lang.entries.firstOrNull { it.code == c } ?: Lang.EN
    }

    fun set(ctx: Context, l: Lang) {
        lang = l
        ctx.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putString("lang", l.code).apply()
    }

    fun t(key: String, vararg args: Any?): String {
        val row = T[key] ?: return key
        val s = row.getOrNull(lang.ordinal)?.takeIf { it.isNotEmpty() } ?: row[0]
        return if (args.isEmpty()) s else try { String.format(s, *args) } catch (e: Exception) { s }
    }

    fun kindLabel(k: DiscKind) = t("kind_" + k.name.lowercase().substringBefore('_').let { if (k == DiscKind.UNKNOWN) "unknown" else it })
    fun kindDetail(k: DiscKind) = t("kindd_" + k.name.lowercase())
    fun profile(p: DiscProfile) = when (p) { DiscProfile.NONE -> t("p_none"); DiscProfile.UNKNOWN -> t("p_unknown"); else -> p.label }

    fun aacs(f: AacsResult.Failed): String = when (f.code) {
        "no_keydb", "not_listed", "mek_only", "no_keys", "uhd", "bad_inf", "missing_uk" -> t("aacs_" + f.code, f.arg)
        else -> f.message
    }

